using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Valora.Application.Journey;
namespace Valora.Web.Controllers;[Authorize][Route("Journey")]public sealed class JourneyController(JourneyService service,JourneyEventService events):Controller{Guid O=>Guid.TryParse(User.FindFirstValue("organization_id")??User.FindFirstValue("organizationId"),out var x)?x:Guid.Empty;Guid U=>Guid.TryParse(User.FindFirstValue(ClaimTypes.NameIdentifier)??User.FindFirstValue("sub"),out var x)?x:Guid.Empty;[HttpGet("")]public async Task<IActionResult>Index([FromQuery]JourneyFilter filter,CancellationToken c)=>View(await service.Timeline(O,filter,c));[HttpGet("Details/{id:guid}")]public async Task<IActionResult>Details(Guid id,CancellationToken c){var x=await service.Get(O,id,c);return x is null?NotFound():View(x);}[ValidateAntiForgeryToken,HttpPost("Create")]public async Task<IActionResult>Create(RegisterJourneyEventRequest r,CancellationToken c){var id=await events.Create(O,U,r,c);return RedirectToAction(nameof(Details),new{id});}}
